class ModelTests(unittest.TestCase):
    """Retest the reconstructed M1 domain contracts and invariants."""

    def test_invalid_intervals(self):
        """Reject equal, reversed and aware intervals."""
        for end in (support.NOW, support.NOW - timedelta(minutes=1)):
            with self.subTest(end=end), self.assertRaises(ValueError):
                support.event(end=end)
        with self.assertRaises(ValueError):
            support.event(start=support.NOW.replace(tzinfo=timezone.utc))

    def test_mutation_preserves_valid_values(self):
        """A failed time or price setter must leave the old value intact."""
        event = support.event()
        with self.assertRaises(ValueError):
            event.start = event.end
        with self.assertRaises(ValueError):
            event.price = '0.001'
        self.assertEqual(event.start, support.NOW)
        self.assertEqual(event.price, Decimal('25.00'))

    def test_money_conversion(self):
        """Preserve exact Rappen and reject floating, nonfinite and negative money."""
        self.assertEqual(models.price_from_rappen(2501), Decimal('25.01'))
        self.assertEqual(models.price_to_rappen('25.01'), 2501)
        self.assertIsNone(models.price_to_rappen(None))
        for value in (25.0, '-1', 'NaN', 'Infinity', 'bad', '0.001'):
            with self.subTest(value=value), self.assertRaises(ValueError):
                support.event(price=value)

    def test_labels_and_tags(self):
        """Show all required event metadata and distinguish free from unknown prices."""
        event = support.event(end_is_estimated=True, members_only=True,
                              status='apply', location_type='tba')
        self.assertEqual(event.display_tags(),
                         ['Estimated end', 'Members only', 'CHF 25.00', 'Apply', 'Location TBA'])
        self.assertEqual(support.event(price='0').price_label(), 'Free')
        self.assertEqual(support.event(price=None).price_label(), '')

    def test_status_and_location(self):
        """Reject unsupported classifications."""
        with self.assertRaises(ValueError):
            support.event(status='invalid')
        with self.assertRaises(ValueError):
            support.event(location_type='invalid')

    def test_overlap_and_midnight(self):
        """Use half-open intervals and count a final midnight as single-day."""
        event = support.event()
        self.assertAlmostEqual(event.overlap_minutes(event.start, event.end), 120)
        self.assertAlmostEqual(event.overlap_minutes(event.end, event.end + timedelta(hours=1)), 0)
        midnight = datetime(2026, 11, 3)
        self.assertFalse(support.event(end=midnight).is_multi_day())
        self.assertTrue(support.event(end=midnight + timedelta(minutes=1)).is_multi_day())

    def test_busy_and_suggestion(self):
        """Keep private titles out of representations and validate normalized scores."""
        block = models.BusyBlock(support.NOW, support.NOW + timedelta(hours=1), 'Private')
        self.assertNotIn('Private', str(block))
        suggestion = models.Suggestion(support.event(), 0.82, [], invited_by='Lena')
        self.assertEqual(suggestion.match_label(), 'Match 82 %')
        self.assertTrue(suggestion.is_invited())
        for score in (-0.1, 1.1, float('nan')):
            with self.subTest(score=score), self.assertRaises(ValueError):
                suggestion.score = score

    def test_profile_favorites(self):
        """Match all three favorite kinds and validate visible display names."""
        profile = models.UserProfile(1, ' Alex ', 'ALEX23', {'career'}, {1}, {4}, {'career_tech'})
        self.assertTrue(profile.wants_direction(support.event()))
        kinds = profile.favorite_kinds(support.event(club_id=4))
        self.assertEqual(kinds, ['series', 'club', 'bundle'])
        for name in ('', 'A', 'A' * 21, 'A\nB'):
            with self.subTest(name=name), self.assertRaises(ValueError):
                profile.display_name = name


class FoundationTests(support.DatabaseCase):
    """Verify reconstructed persistence, taxonomy, source parsing and deterministic demo data."""

    def test_schema_and_foreign_keys(self):
        """Create all thirteen tables idempotently and reject orphan events."""
        database.init_db(self.connection)
        self.assertEqual(self.scalar("SELECT COUNT(*) FROM sqlite_master WHERE type='table'"), 13)
        self.assertEqual(self.scalar('PRAGMA foreign_keys'), 1)
        with self.assertRaises(sqlite3.IntegrityError):
            database.upsert_event(self.connection, 999, support.NOW,
                                  support.NOW + timedelta(hours=1))

    def test_parameterized_settings(self):
        """Treat SQL-looking text as a value and return defaults for missing keys."""
        value = "x'); DROP TABLE events; --"
        database.set_setting(self.connection, 'test', value)
        self.assertEqual(database.get_setting(self.connection, 'test'), value)
        self.assertEqual(database.get_setting(self.connection, 'absent', 'fallback'), 'fallback')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)

    def seed_users(self):
        """Insert two isolated fixture users without implementing M3 onboarding."""
        with self.connection:
            self.connection.executemany('''INSERT INTO users
                (id,display_name,friend_code,created_at) VALUES (?,?,?,?)''',
                [(1, 'Alex', 'ALEX23', database.to_db_text(support.NOW)),
                 (2, 'Lena', 'LENA23', database.to_db_text(support.NOW))])

    def test_calendar_confirmations_are_user_scoped_and_overlap_based(self):
        """Include an overnight confirmation but exclude cancellations and another user's rows."""
        self.seed_users()
        database.set_setting(self.connection, 'current_user_id', '1')
        rows = []
        for index in range(4):
            rows.append(support.record(external_id=str(index),
                                       start=support.NOW - timedelta(hours=11),
                                       end=support.NOW + timedelta(hours=1)))
        self.save(rows)
        with self.connection:
            self.connection.executemany('''INSERT INTO interactions
                (user_id,event_id,status,confirmed_at) VALUES (?,?,?,?)''',
                [(1, 1, 'confirmed', database.to_db_text(support.NOW)),
                 (1, 2, 'cancelled', database.to_db_text(support.NOW)),
                 (2, 3, 'confirmed', database.to_db_text(support.NOW))])
        found = database.get_calendar_confirmations(
            self.connection, support.NOW, support.NOW + timedelta(days=1))
        self.assertEqual(list(found.index), [1])
        database.set_setting(self.connection, 'current_user_id', '2')
        found = database.get_calendar_confirmations(
            self.connection, support.NOW, support.NOW + timedelta(days=1))
        self.assertEqual(list(found.index), [3])

    def test_cleanup_preserves_history_and_invitations(self):
        """Remove only ended occurrences with no interaction or invitation references."""
        self.seed_users()
        rows = []
        for index in range(3):
            rows.append(support.record(external_id=str(index),
                                       start=support.NOW - timedelta(days=2),
                                       end=support.NOW - timedelta(days=1)))
        self.save(rows, include_past=True)
        with self.connection:
            self.connection.execute('''INSERT INTO interactions
                (user_id,event_id,status,confirmed_at) VALUES (?,?,?,?)''',
                (1, 1, 'cancelled', database.to_db_text(support.NOW)))
            self.connection.execute('''INSERT INTO invitations
                (sender_id,recipient_id,event_id,created_at) VALUES (?,?,?,?)''',
                (1, 2, 2, database.to_db_text(support.NOW)))
        self.assertEqual(database.delete_past_unconfirmed_events(self.connection, support.NOW), 1)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 2)

    def test_rating_constraints(self):
        """Reject out-of-range ratings and ratings before attendance is recorded."""
        self.seed_users()
        self.save()
        for status, rating in [('attended', 0), ('attended', 6), ('confirmed', 4)]:
            with self.assertRaises(sqlite3.IntegrityError), self.connection:
                self.connection.execute('''INSERT INTO interactions
                    (user_id,event_id,status,rating,confirmed_at) VALUES (?,?,?,?,?)''',
                    (1, 1, status, rating, database.to_db_text(support.NOW)))

    def test_upsert_identity_and_exclusive_range(self):
        """Keep IDs stable on refresh and honor inclusive/exclusive query boundaries."""
        self.save()
        event_id = self.scalar('SELECT id FROM events')
        self.save([support.record(title='Updated', status='full')])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 1)
        self.assertEqual(database.get_event_row(self.connection, event_id)['status'], 'full')
        start = support.record()['start']
        self.assertTrue(database.get_events_df(self.connection, support.NOW, start).empty)
        self.assertEqual(len(database.get_events_df(self.connection, start,
                                                    start + timedelta(hours=1))), 1)

    def test_atomic_batch(self):
        """Roll back earlier inserts when a later row has an invalid category reference."""
        good = importers.normalize_record(support.record())
        good['bundle_key'] = 'career_tech'
        bad = good.copy()
        bad.update(bundle_key='missing', external_id='bad')
        with self.assertRaises(ValueError):
            database.apply_source_records(self.connection, [good, bad], 'uniclubs')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM clubs'), 0)

    def test_row_factory(self):
        """Build each source subclass from the shared joined database row format."""
        classes = {'unisport': models.UnisportCourse, 'uniclubs': models.ClubEvent,
                   'city': models.CityEvent}
        for source, expected in classes.items():
            importers.save_records(self.connection, [support.record(source=source)], source,
                                   self.taxonomy, now=support.NOW)
            event = models.event_from_row(database.get_event_row(
                self.connection, self.scalar('SELECT MAX(id) FROM events')))
            self.assertIsInstance(event, expected)
            self.assertTrue(event.source_label())

    def test_taxonomy_validation(self):
        """Enforce unique bundle keys and exactly one Other per direction."""
        for modification in ('duplicate', 'missing_other'):
            broken = copy.deepcopy(self.taxonomy)
            if modification == 'duplicate':
                broken['bundles'].append(broken['bundles'][0])
            else:
                broken['bundles'] = [row for row in broken['bundles'] if not row['is_other']]
            with self.subTest(modification=modification), self.assertRaises(ValueError):
                categories.validate_taxonomy(broken)

    def test_keywords(self):
        """Match words, plurals and whole phrases without substring false positives."""
        text = categories.normalize_text('Raclette, concerts and TABLE-tennis!')
        self.assertFalse(categories.keyword_matches('ai', set(text.split()), text))
        self.assertTrue(categories.keyword_matches('concert', set(text.split()), text))
        self.assertTrue(categories.keyword_matches('table tennis', set(text.split()), text))
        self.assertEqual(categories.bundle_score({'keywords': ['python']}, 'Python', 'Python'), 3)

    def test_category_precedence_and_ties(self):
        """Apply trip overrides, club rules, keyword fallback, Other and stable ties."""
        cases = [({'event_type': 'Trip'}, ('leisure', 'leisure_trips')),
                 ({'title': 'Investment', 'club_category': 'Business'},
                  ('career', 'career_finance')),
                 ({'title': 'Banking software'}, ('career', 'career_finance')),
                 ({'title': 'Unspecified', 'club_category': ''}, ('leisure', 'leisure_other')),
                 ({'source': 'unisport', 'title': 'Unspecified'}, ('sports', 'sports_other'))]
        for changes, expected in cases:
            with self.subTest(changes=changes):
                actual = categories.assign_category(support.record(**changes), self.taxonomy)
                self.assertEqual(actual, expected)

    def test_location_normalization(self):
        """Preserve online/TBA precedence and local fallback."""
        for value, expected in [('Zoom Zurich', 'online'), ('', 'tba'), ('Prague', 'elsewhere'),
                                ('SQUARE', 'st_gallen'), ('Unknown venue', 'st_gallen')]:
            self.assertEqual(importers.classify_location(value), expected)

    def test_record_normalization(self):
        """Estimate ends, parse money and normalize membership without bool-string errors."""
        row = importers.normalize_record(support.record(end=None, status='Members Only'))
        self.assertEqual(row['end'] - row['start'], timedelta(minutes=90))
        self.assertTrue(row['end_is_estimated'])
        self.assertTrue(row['members_only'])
        for text, price in [('CHF 25.00', Decimal('25.00')), ('free', Decimal('0')), (None, None)]:
            self.assertEqual(importers.normalize_record(support.record(price=text))['price'], price)
        normalized = importers.normalize_record(support.record(members_only='false'))
        self.assertFalse(normalized['members_only'])

    def test_weekly_expansion(self):
        """Use German/English names and inclusive validity endpoints."""
        for name in ('Thursday', 'Do.', 'Donnerstag', 'thu'):
            intervals = importers.expand_weekly_course(name, time(18, 30), time(20),
                                                      date(2026, 11, 1), date(2026, 11, 30))
            self.assertEqual(len(intervals), 4)
            self.assertEqual(intervals[0][0], datetime(2026, 11, 5, 18, 30))

    def test_payload_shapes_and_timestamp_boundary(self):
        """Support list/envelope formats, nested clubs and aware dates."""
        raw = {'id': 'x', 'title': 'Python', 'start': '2026-11-03T12:00:00Z',
               'club': {'name': 'Tech', 'category': 'Academic'}, 'price': 2.5}
        for payload in ([raw], {'events': [raw]}):
            rows = importers.parse_uniclubs_payload(payload, config.UNICLUBS_FIELD_MAPPING)
            self.assertEqual(rows[0]['start'], datetime(2026, 11, 3, 13))
            self.assertEqual(rows[0]['price'], Decimal('2.5'))
            self.assertTrue(importers.normalize_record(rows[0])['end_is_estimated'])

    def test_invalid_rows_and_limits(self):
        """Count invalid rows and reject oversized imports before changing the database."""
        result = self.save([support.record(), support.record(title=''), support.record(end='bad')])
        self.assertEqual(len(result['skipped']), 2)
        with patch.object(config, 'MAX_RECORDS_PER_SOURCE', 1), self.assertRaises(ValueError):
            self.save([support.record(), support.record()])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 1)

    def test_past_records(self):
        """Skip ended records normally but allow demo initialization to include history."""
        row = support.record(start=support.NOW - timedelta(days=2),
                             end=support.NOW - timedelta(days=1))
        self.assertEqual(self.save([row])['past'], 1)
        self.assertEqual(self.save([row], include_past=True)['n_events'], 1)

    def test_real_excel_mapping(self):
        """Read workbook bytes with translated headers and exact numeric prices."""
        path = self.directory / 'course.xlsx'
        pd.DataFrame([{'Name': 'Yoga', 'date': '2026-11-05', 'start_time': '12:15',
                       'end_time': '13:15', 'price_chf': 2.5}]).to_excel(path, index=False)
        rows = importers.load_unisport_excel(path, {'Name': 'title'}, now=support.NOW)
        self.assertEqual(rows[0]['price'], Decimal('2.5'))
        self.assertFalse(rows[0]['is_recurring'])

    def test_demo_counts_and_repeatability(self):
        """Restore the M1 counts, closed statuses, bundles and stable identities."""
        reports = synthetic_data.generate_all(self.connection, support.NOW.date(), **self.paths)
        self.assertEqual([row['n_events'] for row in reports], [480, 60, 30])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 130)
        self.assertEqual(self.scalar("SELECT COUNT(*) FROM events WHERE status='full'"), 3)
        self.assertEqual(self.scalar("SELECT COUNT(*) FROM events WHERE status='closed'"), 2)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series WHERE bundle_id IS NULL'), 0)
        before = [tuple(row) for row in self.connection.execute('SELECT * FROM events')]
        synthetic_data.generate_all(self.connection, support.NOW.date(), **self.paths)
        after = [tuple(row) for row in self.connection.execute('SELECT * FROM events')]
        self.assertEqual(before, after)

    def test_seeded_sources(self):
        """Reproduce JSON bytes and Excel values with a fixed anchor."""
        first = synthetic_data.write_placeholder_sources(support.NOW.date(), self.directory / 'a')
        second = synthetic_data.write_placeholder_sources(support.NOW.date(), self.directory / 'b')
        self.assertEqual(first['city'].read_bytes(), second['city'].read_bytes())
        self.assertEqual(first['uniclubs'].read_bytes(), second['uniclubs'].read_bytes())
        pd.testing.assert_frame_equal(pd.read_excel(first['unisport']),
                                      pd.read_excel(second['unisport']))


class FallbackTests(support.DatabaseCase):
    """Retest M1 fallback, rejection, confidentiality and snapshot preservation."""

    def setUp(self):
        """Create isolated placeholders and a dummy private source configuration."""
        super().setUp()
        synthetic_data.write_placeholder_sources(support.NOW.date(), self.paths['sources_dir'])
        self.paths['snapshot_dir'].mkdir()
        settings = {'uniclubs': {'url': 'https://example.invalid/private-secret',
                                 'token': 'dummy-secret'}}
        self.paths['private_file'].write_text(json.dumps(settings))

    def run_source(self):
        """Import the configured fixture source at a fixed time."""
        return importers.import_source(self.connection, 'uniclubs', self.taxonomy,
                                       now=support.NOW, **self.paths)

    def test_default_offline(self):
        """Use placeholders without any network call when no URL is configured."""
        self.paths['private_file'].unlink()
        with patch.object(importers, 'fetch_json', side_effect=AssertionError('No network')):
            self.assertEqual(self.run_source()['origin'], 'placeholder')

    def test_snapshot_fallback_redaction(self):
        """Use the snapshot after a network failure without exposing its secret URL."""
        path = self.paths['snapshot_dir'] / 'uniclubs.json'
        path.write_text(json.dumps([{'id': 'snapshot', 'title': 'Stored',
                                    'start': '2026-11-04T12:00:00'}]))
        failure = importers.requests.Timeout('secret')
        with patch.object(importers, 'fetch_json', side_effect=failure):
            report = self.run_source()
        self.assertEqual(report['origin'], 'snapshot')
        self.assertNotIn('secret', report['message'])
        self.assertEqual(len(database.get_import_log_df(self.connection)), 1)

    def test_rejected_empty_live_preserves_data(self):
        """Keep stored records and snapshots when a live source is unexpectedly empty."""
        self.save()
        path = self.paths['snapshot_dir'] / 'uniclubs.json'
        path.write_text('last-good-snapshot')
        with patch.object(importers, 'fetch_json', return_value=[]):
            self.assertEqual(self.run_source()['outcome'], 'rejected')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 1)
        self.assertEqual(path.read_text(), 'last-good-snapshot')

    def test_successful_live_reconciliation(self):
        """Delete absent unreferenced future events only on an accepted live refresh."""
        self.save()
        payload = [{'id': 'new', 'title': 'New', 'start': '2026-11-05T12:00:00'}]
        with patch.object(importers, 'fetch_json', return_value=payload):
            self.assertEqual(self.run_source()['origin'], 'live')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 1)
        snapshot = self.paths['snapshot_dir'] / 'uniclubs.json'
        self.assertEqual(json.loads(snapshot.read_text()), payload)

    def test_fallback_and_partial_import_keep_existing_records(self):
        """Do not infer organizer cancellation from fallback or partially invalid data."""
        self.save()
        payload = [{'id': 'new', 'title': 'New', 'start': '2026-11-05T12:00:00'}, {'title': 'Bad'}]
        with patch.object(importers, 'fetch_json', return_value=payload):
            self.run_source()
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 2)
        self.paths['private_file'].unlink()
        (self.paths['snapshot_dir'] / 'uniclubs.json').write_text('invalid')
        self.assertEqual(self.run_source()['origin'], 'placeholder')
        self.assertIsNotNone(database.get_event_row(self.connection, 1))

    def test_upstream_diagnostics_cannot_leak(self):
        """Ignore untrusted internal diagnostic fields in upstream JSON."""
        payload = [{'id': 'x', 'title': 'Good', 'start': '2026-11-05T12:00:00', '_error': 'secret'}]
        rows = importers.parse_uniclubs_payload(payload, config.UNICLUBS_FIELD_MAPPING)
        self.assertEqual(self.save(rows)['skipped'], [])
